import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:]]

    counts = Counter(a)
    ans = 0
    for count in counts.values():
        if count % 2 == 1:
            ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

